/**
 * Test flow for sendEmail action
 * Demonstrates sending an email
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testSendEmail = Flow(
    {
        $id: Now.ID['test_send_email_flow'],
        name: 'Test Send Email',
        description: 'Tests the sendEmail core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_send_email_trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        const result = wfa.action(
            action.core.sendEmail,
            { $id: Now.ID['test_send_email_action'] },
            {
                ah_to: 'user@example.com',
                ah_subject: `Incident ${wfa.dataPill(_params.trigger.current.number, 'integer')} created`,
                ah_body: 'An incident has been created. Please review and take appropriate action.',
                record: wfa.dataPill(_params.trigger.current.sys_id, 'reference'),
                table_name: 'incident',
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_send_email_log'] },
            {
                log_level: 'info',
                log_message: `sendEmail outputs: email=${wfa.dataPill(result.email, 'reference')}`,
            }
        )
    }
)
